is IAsyncDisposable a)await a.DisposeAsync();else if(module is IDisposable b)b.Dispose();}catch(Exception ex){error??=ex;}}
   if(cancellationToken.IsCancellationRequested){Record(NodeRunStatus.Cancelled,code:"Cancelled");continue;}if(timeout.IsCancellationRequested){Record(NodeRunStatus.TimedOut,code:"Timeout",message:"Cooperative module timeout");continue;}if(error is not null){Record(NodeRunStatus.Failed,code:"ModuleException",message:error.Message);continue;}if(result is null){Record(NodeRunStatus.Failed,code:"InvalidResult");continue;}if(!Enum.IsDefined(result.Status)){Record(NodeRunStatus.Failed,code:"InvalidResult",message:"Unknown module status");continue;}if(result.Status==ModuleStatus.Failed&&!result.PreserveFailedOutputs){Record(NodeRunStatus.Failed,code:result.ErrorCode??"ModuleFailed",message:result.Message,nativeCode:result.NativeErrorCode);continue;}
